class Graph:
    def __init__(self):
        self._nodes = set()
        self.edges = {}

    def add_node(self, n):
        self.nodes.add(n)

    def add_edge(self, a, b, weight=1):
        if weight <= 0:
            raise ValueError("Weight must be a positive number")
        if a not in self.nodes:
            self.add_node(a)
        if b not in self.nodes:
            self.add_node(b)
        self.edges[(a, b)] = weight

    def nodes(self):
        return sorted(self.nodes)

    def neighbors(self, a):
        return sorted([(b, self.edges[(a, b)]) for b in self.edges if b[0] == a])

if __name__ == "__main__":
    # Test cases
    g = Graph()
    g.add_node(1)
    g.add_node(2)
    g.add_edge(1, 2, 3)
    g.add_edge(2, 1, 4)
    g.add_edge(1, 2, 5)  # Should replace the weight to 5

    assert g.nodes() == [1, 2]
    assert g.neighbors(1) == [(2, 5)]
    assert g.neighbors(2) == [(1, 4)]

    try:
        g.add_edge(1, 2, -1)
    except ValueError as e:
        assert str(e) == "Weight must be a positive number"

    print("All tests passed")
    def bfs(self, start):
        if start not in self.nodes:
            raise KeyError(f"Node {start} not found in the graph")
        
        visited = set()
        queue = deque([start])
        result = []

        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                result.append(node)
                for neighbor, _ in self.neighbors(node):
                    if neighbor not in visited:
                        queue.append(neighbor)

        return result

