      cache.set('key1', 'value1');
      assert.strictEqual(cache.get('key1'), 'value1');
      assert.strictEqual(cache.size(), 1);
    });

    it('should update an existing key-value pair', function() {
      const cache = new Cache(5);
      cache.set('key1', 'value1');
      cache.set('key1', 'value2');
