class Gradebook:
    def __init__(self):
        self.students = {}
        self.assignments = {}

    def add_student(self, name):
        if name in self.students:
            raise ValueError("Student already exists")
        self.students[name] = {}

    def add_assignment(self, name, max_points):
        if name in self.assignments:
            raise ValueError("Assignment already exists")
        if max_points <= 0:
            raise ValueError("Max points must be a positive number")
        self.assignments[name] = max_points

    def record(self, student, assignment, points):
        if student not in self.students:
            raise KeyError("Unknown student")
        if assignment not in self.assignments:
            raise KeyError("Unknown assignment")
        if not (0 <= points <= self.assignments[assignment]):
            raise ValueError("Points must be between 0 and max points")
        self.students[student][assignment] = points

    def score(self, student, assignment):
        if student not in self.students:
            raise KeyError("Unknown student")
        if assignment not in self.assignments:
            raise KeyError("Unknown assignment")
        return self.students[student].get(assignment, None)

    def percent(self, student):
        if student not in self.students:
            raise KeyError("Unknown student")
        
        total_points = 0
        total_max_points = 0
        
        for assignment in self.students[student].values():
            total_points += assignment['points']
            total_max_points += assignment['max_points']
        
        if total_max_points == 0:
            return None
        
        return round((total_points / total_max_points) * 100, 2)
if __name__ == "__main__":
    gb = Gradebook()
    gb.add_student("Alice")
    gb.add_assignment("Math", 100)
    gb.record("Alice", "Math", 85)
    assert gb.score("Alice", "Math") == 85
    gb.record("Alice", "Math", 90)
    assert gb.score("Alice", "Math") == 90
    try:
        gb.add_student("Alice")
    except ValueError as e:
        assert str(e) == "Student already exists"
    try:
        gb.add_assignment("Math", 100)
    except ValueError as e:
        assert str(e) == "Max points must be a positive number"
    try:
        gb.record("Alice", "Science", 85)
    except KeyError as e:
        assert str(e) == "Unknown assignment"
    try:
        gb.record("Bob", "Math", 85)
    except KeyError as e:
        assert str(e) == "Unknown student"
    try:
        gb.record("Alice", "Math", 105)
    except ValueError as e:
        assert str(e) == "Points must be between 0 and max points"
    print("All tests passed")
def letter_grade(percent):
    if percent >= 90:
        return 'A'
    elif percent >= 80:
        return 'B'
    elif percent >= 70:
        return 'C'
    elif percent >= 60:
        return 'D'
    else:
        return 'F'
def report(self):
    report_list = []
    for student in sorted(self.students):
        percent = self.percent(student)
        letter = letter_grade(percent) if percent is not None else '-'
        report_list.append((student, percent, letter))
    return report_list

