    except KeyError as e:
        assert str(e) == "Unknown assignment"
    try:
        gb.record("Bob", "Math", 85)
    except KeyError as e:
        assert str(e) == "Unknown student"
    try:
        gb.record("Alice", "Math", 105)
    except ValueError as e:
        assert str(e) == "Points must be between 0 and max points"
