def letter_grade(percent):
    if percent >= 90:
        return 'A'
    elif percent >= 80:
        return 'B'
    elif percent >= 70:
        return 'C'
    elif percent >= 60:
        return 'D'
    else:
        return 'F'
def report(self):
    report_list = []
    for student in sorted(self.students):
        percent = self.percent(student)
        letter = letter_grade(percent) if percent is not None else '-'
        report_list.append((student, percent, letter))
    return report_list

