        if student not in self.students:
            raise KeyError("Unknown student")
        
        total_points = 0
        total_max_points = 0
        
        for assignment in self.students[student].values():
            total_points += assignment['points']
            total_max_points += assignment['max_points']
        
        if total_max_points == 0:
