            if node in rec_stack:
                return True
            if node in visited:
                return False

            visited.add(node)
            rec_stack.add(node)

            for neighbor in self.neighbors(node):
                if dfs(neighbor):
                    return True

            rec_stack.remove(node)
            return False

        for node in self.nodes():
            if dfs(node):
                return True

        return False
    def topo_order(self):
        visited = set()
        stack = []
        temp_stack = []

        def dfs(node):
            visited.add(node)
            temp_stack.append(node)

            for neighbor in self.neighbors(node):
                if neighbor[0] not in visited:
                    dfs(neighbor[0])
                elif neighbor[0] in temp_stack:
                    raise ValueError("Graph has a cycle")

            temp_stack.remove(node)
            stack.append(node)

        for node in self.nodes():
            if node not in visited:
                dfs(node)

        return stack[::-1]

