    g.add_node(1)
    g.add_node(2)
    g.add_edge(1, 2, 3)
    g.add_edge(2, 1, 4)
    g.add_edge(1, 2, 5)  # Should replace the weight to 5

    assert g.nodes() == [1, 2]
    assert g.neighbors(1) == [(2, 5)]
    assert g.neighbors(2) == [(1, 4)]

    try:
        g.add_edge(1, 2, -1)
    except ValueError as e:
