                return False

            visited.add(node)
            rec_stack.add(node)

            for neighbor in self.neighbors(node):
                if dfs(neighbor):
                    return True

            rec_stack.remove(node)
            return False

        for node in self.nodes():
            if dfs(node):
                return True

        return False
