import re

def parse_line(line):
    # Define the regex pattern for the log line
    pattern = r'(\S+) - - \[(.*?)\] "(GET|POST|PUT|DELETE) (\S+)" (\d+) (\d+|-) (\d+\.\d+)'
    
    # Match the line against the pattern
    match = re.match(pattern, line)
    
    if not match:
        raise ValueError("Line does not match the expected format")
    
    # Extract the fields from the match
    ip = match.group(1)
    time = match.group(2)
    method = match.group(3)
    path = match.group(4)
    status = int(match.group(5))
    bytes = int(match.group(6)) if match.group(6) != '-' else 0
    seconds = float(match.group(7))
    
    # Return the parsed data as a dictionary
    return {
        'ip': ip,
        'time': time,
        'method': method,
        'path': path,
        'status': status,
        'bytes': bytes,
        'seconds': seconds
    }

if __name__ == "__main__":
    # Test cases
    test_line = '127.0.0.1 - - [10/Oct/2023:13:55:36 +0000] "GET /index.html HTTP/1.1" 200 2326 0.045'
    try:
        parsed = parse_line(test_line)
        assert parsed == {
            'ip': '127.0.0.1',
            'time': '10/Oct/2023:13:55:36 +0000',
            'method': 'GET',
            'path': '/index.html',
            'status': 200,
            'bytes': 2326,
            'seconds': 0.045
        }
        print("Test passed")
    except AssertionError:
        print("Test failed")
    except ValueError as e:
        print(f"ValueError: {e}")
def parse_log(text):
    lines = text.splitlines()
    parsed_logs = []
    malformed_lines = []

    for i, line in enumerate(lines, start=1):
        try:
            parsed_logs.append(parse_line(line))
        except ValueError:
            malformed_lines.append(i)

    return parsed_logs, malformed_lines
def bad_lines(text):
    lines = text.splitlines()
    malformed_lines = []

    for i, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            parse_line(line)
        except ValueError:
            malformed_lines.append(i)

    return malformed_lines
def status_counts(entries):
    counts = {}
    for entry in entries:
        status = entry['status']
        if status in counts:
            counts[status] += 1
        else:
            counts[status] = 1
    return counts
def error_rate(entries):
    if not entries:
        return 0.0
    error_count = sum(1 for entry in entries if entry['status'] >= 500)
    return round(error_count / len(entries), 4)
def top_paths(entries, n=3):
    from urllib.parse import urlparse
    from collections import Counter

    path_counts = Counter()

    for entry in entries:
        parsed_url = urlparse(entry)
        path = parsed_url.path
        path_counts[path] += 1

    return path_counts.most_common(n)
def percentile(entries, p):
    if not 0 < p <= 100:
        raise ValueError("p must be between 0 and 100")
    if not entries:
        raise ValueError("entries must not be empty")
    
    sorted_entries = sorted(entries)
    index = int((len(sorted_entries) - 1) * p / 100)
    return sorted_entries[index]
def test_percentile():
    entries = [1, 2, 3, 4, 5]
    assert percentile(entries, 50) == 3
    assert percentile(entries, 25) == 2
    assert percentile(entries, 75) == 4
    assert percentile(entries, 100) == 5
    assert percentile(entries, 1) == 1
    print("All test cases passed!")

if __name__ == "__main__":
    test_percentile()
def by_hour(entries):
    from collections import defaultdict
    from datetime import datetime

    hourly_totals = defaultdict(int)

    for entry in entries:
        time_str = entry['time'].replace('+0000', '')
        dt = datetime.strptime(time_str, '%Y-%m-%d %H:%M:%S')
        hour_key = dt.strftime('%Y-%m-%d %H')
        hourly_totals[hour_key] += entry['bytes']

    return dict(hourly_totals)
def test_by_hour():
    entries = [
        {'time': '2023-10-01 12:30:00+0000', 'bytes': 100},
        {'time': '2023-10-01 12:45:00+0000', 'bytes': 200},
        {'time': '2023-10-01 13:00:00+0000', 'bytes': 150},
        {'time': '2023-10-02 12:00:00+0000', 'bytes': 300},
    ]
    expected = {
        '2023-10-01 12': 300,
        '2023-10-01 13': 150,
        '2023-10-02 12': 300,
