        if n not in self.nodes:
            raise KeyError(f"Node {n} not found in the graph")
        
        # Remove all edges connected to the node
        edges_to_remove = [edge for edge in self.edges if n in edge]
        for edge in edges_to_remove:
            del self.edges[edge]
        
