                    output.push(operators.pop());
                }
                operators.push(char);
                continue;
            }

            if (char === '(') {
                operators.push(char);
                continue;
            }

            if (char === ')') {
                while (operators.length > 0 && operators[operators.length - 1] !== '(') {
                    output.push(operators.pop());
                }
                operators.pop();
                continue;
            }

            throw new Error(`Unknown character: ${char}`);
        }

