    def bfs(self, start):
        if start not in self.nodes:
            raise KeyError(f"Node {start} not found in the graph")
        
        visited = set()
        queue = deque([start])
        result = []

        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                result.append(node)
                for neighbor, _ in self.neighbors(node):
                    if neighbor not in visited:
                        queue.append(neighbor)

        return result
    def shortest_path(self, start, end):
        import heapq
        if start not in self.nodes or end not in self.nodes:
            raise KeyError("Node not in graph")

        distances = {node: float('inf') for node in self.nodes}
        distances[start] = 0
        priority_queue = [(0, start)]

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            if current_distance > distances[current_node]:
                continue

            if current_node == end:
                return current_distance, [start]

            for neighbor, weight in self.edges[current_node]:
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        return None, []
    def has_cycle(self):
        visited = set()
        rec_stack = set()

        def dfs(node):
            if node in rec_stack:
                return True
            if node in visited:
                return False

            visited.add(node)
            rec_stack.add(node)

            for neighbor in self.neighbors(node):
                if dfs(neighbor):
                    return True

            rec_stack.remove(node)
            return False

        for node in self.nodes():
            if dfs(node):
                return True

        return False
    def topo_order(self):
        visited = set()
        stack = []
        temp_stack = []

        def dfs(node):
            visited.add(node)
            temp_stack.append(node)

            for neighbor in self.neighbors(node):
                if neighbor[0] not in visited:
                    dfs(neighbor[0])
                elif neighbor[0] in temp_stack:
                    raise ValueError("Graph has a cycle")

            temp_stack.remove(node)
            stack.append(node)

        for node in self.nodes():
            if node not in visited:
                dfs(node)

        return stack[::-1]
    def remove_node(self, n):
        if n not in self.nodes:
            raise KeyError(f"Node {n} not found in the graph")
        
        # Remove all edges connected to the node
        edges_to_remove = [edge for edge in self.edges if n in edge]
        for edge in edges_to_remove:
            del self.edges[edge]
        
        # Remove the node from the set of nodes
        self.nodes.remove(n)
    def reachable(self, a):
        if a not in self.nodes():
            raise KeyError(f"Node {a} is not in the graph")
        visited = set()
        stack = [a]
        reachable_nodes = []

        while stack:
            node = stack.pop()
            if node not in visited:
                visited.add(node)
                reachable_nodes.append(node)
                stack.extend(self.neighbors(node))

        return sorted(reachable_nodes)

