import re

def parse_line(line):
    # Define the regex pattern for the log line
    pattern = r'(\S+) - - \[(.*?)\] "(GET|POST|PUT|DELETE) (\S+)" (\d+) (\d+|-) (\d+\.\d+)'
    
    # Match the line against the pattern
    match = re.match(pattern, line)
    
    if not match:
        raise ValueError("Line does not match the expected format")
    
    # Extract the fields from the match
    ip = match.group(1)
    time = match.group(2)
    method = match.group(3)
    path = match.group(4)
    status = int(match.group(5))
    bytes = int(match.group(6)) if match.group(6) != '-' else 0
    seconds = float(match.group(7))
    
    # Return the parsed data as a dictionary
    return {
        'ip': ip,
        'time': time,
        'method': method,
        'path': path,
        'status': status,
        'bytes': bytes,
        'seconds': seconds
    }

if __name__ == "__main__":
    # Test cases
    test_line = '127.0.0.1 - - [10/Oct/2023:13:55:36 +0000] "GET /index.html HTTP/1.1" 200 2326 0.045'
    try:
        parsed = parse_line(test_line)
        assert parsed == {
            'ip': '127.0.0.1',
            'time': '10/Oct/2023:13:55:36 +0000',
            'method': 'GET',
            'path': '/index.html',
            'status': 200,
            'bytes': 2326,
            'seconds': 0.045
        }
        print("Test passed")
    except AssertionError:
        print("Test failed")
    except ValueError as e:
        print(f"ValueError: {e}")

    # Test the between function
    entries = [
        {'ip': '127.0.0.1', 'time': '2023-10-01 12:00:00', 'method': 'GET', 'path': '/index.html', 'status': 200, 'bytes': 2326, 'seconds': 0.045},
        {'ip': '127.0.0.1', 'time': '2023-10-01 13:00:00', 'method': 'GET', 'path': '/index.html', 'status': 200, 'bytes': 2326, 'seconds': 0.045},
        {'ip': '127.0.0.1', 'time': '2023-10-02 12:00:00', 'method': 'GET', 'path': '/index.html', 'status': 200, 'bytes': 2326, 'seconds': 0.045},
    ]
    start = '2023-10-01 12:00:00'
    end = '2023-10-01 14:00:00'
    filtered_entries = between(entries, start, end)
    assert filtered_entries == [
        {'ip': '127.0.0.1', 'time': '2023-10-01 12:00:00', 'method': 'GET', 'path': '/index.html', 'status': 200, 'bytes': 2326, 'seconds': 0.045},
        {'ip': '127.0.0.1', 'time': '2023-10-01 13:00:00', 'method': 'GET', 'path': '/index.html', 'status': 200, 'bytes': 2326, 'seconds': 0.045},
    ]
    print("Test passed for between function")
def parse_log(text):
    lines = text.splitlines()
    parsed_logs = []
    malformed_lines = []

    for i, line in enumerate(lines, start=1):
        try:
            parsed_logs.append(parse_line(line))
        except ValueError:
            malformed_lines.append(i)

    return parsed_logs, malformed_lines
def bad_lines(text):
    lines = text.splitlines()
    malformed_lines = []

    for i, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            parse_line(line)
        except ValueError:
            malformed_lines.append(i)

    return malformed_lines
def status_counts(entries):
    counts = {}
    for entry in entries:
        status = entry['status']
        if status in counts:
            counts[status] += 1
        else:
            counts[status] = 1
    return counts
def error_rate(entries):
    if not entries:
        return 0.0
    error_count = sum(1 for entry in entries if entry['status'] >= 500)
    return round(error_count / len(entries), 4)
def top_paths(entries, n=3):
    from urllib.parse import urlparse
    from collections import Counter

    path_counts = Counter()

    for entry in entries:
        parsed_url = urlparse(entry)
        path = parsed_url.path
        path_counts[path] += 1

    return path_counts.most_common(n)
def percentile(entries, p):
    if not 0 < p <= 100:
        raise ValueError("p must be between 0 and 100")
    if not entries:
        raise ValueError("entries must not be empty")
    
    sorted_entries = sorted(entries)
    index = int((len(sorted_entries) - 1) * p / 100)
    return sorted_entries[index]
def test_percentile():
    entries = [1, 2, 3, 4, 5]
    assert percentile(entries, 50) == 3
    assert percentile(entries, 25) == 2
    assert percentile(entries, 75) == 4
    assert percentile(entries, 100) == 5
    assert percentile(entries, 1) == 1
    print("All test cases passed!")

if __name__ == "__main__":
    test_percentile()
def by_hour(entries):
    from collections import defaultdict
    from datetime import datetime

    hourly_totals = defaultdict(int)

    for entry in entries:
        time_str = entry['time'].replace('+0000', '')
        dt = datetime.strptime(time_str, '%Y-%m-%d %H:%M:%S')
        hour_key = dt.strftime('%Y-%m-%d %H')
        hourly_totals[hour_key] += entry['bytes']

    return dict(hourly_totals)
def test_by_hour():
    entries = [
        {'time': '2023-10-01 12:30:00+0000', 'bytes': 100},
        {'time': '2023-10-01 12:45:00+0000', 'bytes': 200},
        {'time': '2023-10-01 13:00:00+0000', 'bytes': 150},
        {'time': '2023-10-02 12:00:00+0000', 'bytes': 300},
    ]
    expected = {
        '2023-10-01 12': 300,
        '2023-10-01 13': 150,
        '2023-10-02 12': 300,
    }
    assert by_hour(entries) == expected, "Test failed for by_hour function"
from datetime import datetime

def between(entries, start, end):
    start_time = datetime.strptime(start, "%Y-%m-%d %H:%M:%S")
    end_time = datetime.strptime(end, "%Y-%m-%d %H:%M:%S")
    return [entry for entry in entries if start_time <= entry['t'] < end_time]
def between(entries, start, end):
    from datetime import datetime

    start_dt = datetime.strptime(start, '%Y-%m-%d %H:%M:%S')
    end_dt = datetime.strptime(end, '%Y-%m-%d %H:%M:%S')

    filtered_entries = []
    for entry in entries:
        entry_time = datetime.strptime(entry['time'], '%Y-%m-%d %H:%M:%S')
        if start_dt <= entry_time < end_dt:
            filtered_entries.append(entry)

    return filtered_entries
from datetime import datetime, timedelta

def sessions(entries, gap_minutes=30):
    session_dict = {}
    for entry in entries:
        ip = entry['ip']
        timestamp = datetime.strptime(entry['timestamp'], '%Y-%m-%d %H:%M:%S')
        
        if ip not in session_dict:
            session_dict[ip] = 1
        else:
            last_timestamp = datetime.strptime(session_dict[ip][-1]['timestamp'], '%Y-%m-%d %H:%M:%S')
            if (timestamp - last_timestamp) > timedelta(minutes=gap_minutes):
                session_dict[ip].append({'timestamp': timestamp.strftime('%Y-%m-%d %H:%M:%S')})
            else:
                session_dict[ip][-1]['timestamp'] = timestamp.strftime('%Y-%m-%d %H:%M:%S')
    
    return session_dict

