        if ip not in session_dict:
            session_dict[ip] = 1
        else:
            last_timestamp = datetime.strptime(session_dict[ip][-1]['timestamp'], '%Y-%m-%d %H:%M:%S')
            if (timestamp - last_timestamp) > timedelta(minutes=gap_minutes):
                session_dict[ip].append({'timestamp': timestamp.strftime('%Y-%m-%d %H:%M:%S')})
