                if neighbor[0] not in visited:
                    dfs(neighbor[0])
                elif neighbor[0] in temp_stack:
                    raise ValueError("Graph has a cycle")

            temp_stack.remove(node)
            stack.append(node)

        for node in self.nodes():
            if node not in visited:
                dfs(node)

