    const n = expr.length;

    while (i < n) {
        const char = expr[i];

        if (char === ' ') {
            i++;
            continue;
        }

        if (char >= '0' && char <= '9') {
            let value = '';
            while (i < n && (expr[i] >= '0' && expr[i] <= '9')) {
                value += expr[i];
                i++;
